<script>document.addEventListener('DOMContentLoaded',()=>{const side=document.getElementById('side-menu');if(side){side.innerHTML=`<div class="brand"><div class="brand-logo-wrap"><img class="brand-logo" src="{{ route('brand.logo') }}" alt="UNIFCO"></div></div><div class="side-search"><input id="side-nav-search" type="search" placeholder="Search my workspace..." autocomplete="off"></div><div class="nav-section-label">MAINTENANCE MANAGER</div>@foreach($navItems as [$icon,$label,$url])<a class="nav-link {{ $label==='Assets & EAM'?'active':'' }}" href="{{ $url }}"><span class="nav-icon">{{ $icon }}</span><span class="nav-label">{{ $label }}</span>@if($label==='Notifications')<span class="asset360-notify">3</span>@endif</a>@endforeach<div class="nav-section-label">PLATFORM</div><a class="nav-link" href="{{ route('platform.notifications.index') }}"><span class="nav-icon">●</span><span class="nav-label">Notifications</span><span class="asset360-notify">3</span></a><div class="asset360-notice">Navigation is limited to responsibilities for this role.</div><div class="asset360-clock"><span>ENG</span><span>⌁  ◴  9:10 PM</span></div><div class="nav-empty" id="side-nav-empty">No matching items.</div>`}const bs=[...document.querySelectorAll('#a360tabs [data-tab]')],ps=[...document.querySelectorAll('.a360 .pane')];const open=n=>{bs.forEach(b=>b.classList.toggle('active',b.dataset.tab===n));ps.forEach(p=>p.classList.toggle('active',p.id==='tab-'+n));history.replaceState(null,'','#'+n)};bs.forEach(b=>b.onclick=()=>open(b.dataset.tab));document.querySelectorAll('[data-tab-open]').forEach(b=>b.onclick=()=>open(b.dataset.tabOpen));const h=location.hash.slice(1);open(bs.some(b=>b.dataset.tab===h)?h:'overview')});</script>
